public struct AbiVersion: Equatable, Hashable {
    public var abiVersion: UInt32
    public var schema: String
    public var profile: String
    public var offsetUnits: String
    public var updateEncoding: UInt32
    public var uniffiVersion: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(abiVersion: UInt32, schema: String, profile: String, offsetUnits: String, updateEncoding: UInt32, uniffiVersion: String) {
        self.abiVersion = abiVersion
        self.schema = schema
        self.profile = profile
        self.offsetUnits = offsetUnits
        self.updateEncoding = updateEncoding
        self.uniffiVersion = uniffiVersion
    }

    

    
}

